package com.classroom.modules.assessment.doc;

import com.classroom.common.AppException;
import com.classroom.modules.assessment.grading.GradingEngine;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class AssessmentInterchangeTest {
    @Test void wordImagesTablesAndOfficeFractionsBecomeContent(){
        String body="<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main' xmlns:m='http://schemas.openxmlformats.org/officeDocument/2006/math' xmlns:a='http://schemas.openxmlformats.org/drawingml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><w:body><w:p><w:r><w:t>Đề Word</w:t></w:r></w:p><w:p><w:r><w:t>Câu 1: Tính </w:t></w:r><m:oMath><m:f><m:num><m:r><m:t>1</m:t></m:r></m:num><m:den><m:r><m:t>2</m:t></m:r></m:den></m:f></m:oMath><w:r><w:drawing><a:blip r:embed='rId1'/></w:drawing></w:r></w:p><w:tbl><w:tr><w:tc><w:p><w:r><w:t>Dữ kiện</w:t></w:r></w:p></w:tc><w:tc><w:p><w:r><w:t>5</w:t></w:r></w:p></w:tc></w:tr></w:tbl><w:p><w:r><w:t>A. 0.5</w:t></w:r></w:p><w:p><w:r><w:t>B. 2</w:t></w:r></w:p><w:p><w:r><w:t>Đáp án: A</w:t></w:r></w:p></w:body></w:document>";
        Map<String,byte[]> entries=new LinkedHashMap<>();entries.put("word/document.xml",body.getBytes(StandardCharsets.UTF_8));entries.put("word/_rels/document.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Target='media/image.png'/></Relationships>".getBytes(StandardCharsets.UTF_8));entries.put("word/media/image.png",Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a04kAAAAASUVORK5CYII="));
        byte[] zip;try{var out=new java.io.ByteArrayOutputStream();try(var writer=new java.util.zip.ZipOutputStream(out)){for(var e:entries.entrySet()){writer.putNextEntry(new java.util.zip.ZipEntry(e.getKey()));writer.write(e.getValue());writer.closeEntry();}}zip=out.toByteArray();}catch(java.io.IOException e){throw new AssertionError(e);}
        var imported=AssessmentInterchange.read(zip,"word.docx");var q=DocumentIndex.of(imported.document()).items().get(0).item();assertTrue(q.prompt().contains("\\frac{1}{2}"));assertEquals(List.of("IMAGE","TABLE"),q.promptBlocks().stream().map(ContentBlock::type).toList());assertEquals(1,imported.embeddedAssets().size());assertEquals("image/png",imported.embeddedAssets().values().iterator().next().mime());assertEquals("o0",q.answerKey().path("optionId").asText());
    }
    @Test void csvEscapesSpreadsheetFormulasWithoutChangingImportedContent(){var doc=sample();var tree=(com.fasterxml.jackson.databind.node.ObjectNode)DocumentCodec.toTree(doc);((com.fasterxml.jackson.databind.node.ObjectNode)tree.path("sections").get(0).path("nodes").get(0)).put("prompt","=HYPERLINK(\"https://invalid.example\")");doc=DocumentCodec.parse(tree);var export=AssessmentInterchange.write(doc,"csv");String csv=new String(export.bytes(),StandardCharsets.UTF_8);assertTrue(csv.contains("'=HYPERLINK"));assertEquals(DocumentCodec.canonicalHash(doc),DocumentCodec.canonicalHash(AssessmentInterchange.read(export.bytes(),"test.csv").document()));}
    @Test void rootSectionAndOptionAudioCarryInheritedLimitsWithoutSecrets(){var doc=sample();var tree=(com.fasterxml.jackson.databind.node.ObjectNode)DocumentCodec.toTree(doc);tree.put("audioAssetKey","root");tree.set("playback",DocumentCodec.toTree(new PlaybackPolicy(2,false,false,false,3)));tree.set("assets",DocumentCodec.readTree("{\"root\":{\"assetId\":\"00000000-0000-0000-0000-000000000001\",\"type\":\"AUDIO\",\"transcript\":\"hidden transcript\"},\"option\":{\"assetId\":\"00000000-0000-0000-0000-000000000002\",\"type\":\"AUDIO\"}}"));((com.fasterxml.jackson.databind.node.ObjectNode)tree.path("sections").get(0).path("nodes").get(0).path("interaction").path("options").get(0)).put("audioAssetKey","option");doc=DocumentCodec.parse(tree);assertEquals(2,AudioPolicies.forAsset(doc,"option").maxPlays());String projection=DocumentCodec.writeJson(LearnerProjection.project(doc,0,false,null));assertTrue(projection.contains("audioAssetKey"));assertFalse(projection.contains("hidden transcript"));assertFalse(projection.contains("answerKey"));assertEquals("root",LearnerProjection.ordered(doc,1,true).audioAssetKey());}
    @Test void qtiUsesPointsAndSingleTextResponseWithAlternativeMatches(){
        var tree=(com.fasterxml.jackson.databind.node.ObjectNode)DocumentCodec.toTree(sample());var item=(com.fasterxml.jackson.databind.node.ObjectNode)tree.path("sections").get(0).path("nodes").get(0);
        item.put("type","Q10");item.put("points",2.5);item.set("interaction",DocumentCodec.readTree("{}"));item.set("answerKey",DocumentCodec.readTree("{\"accepted\":[\"five\",\"5\"]}"));
        var files=AssessmentInterchange.unzip(AssessmentInterchange.write(DocumentCodec.parse(tree),"qti").bytes());String xml=new String(files.get("item1.xml"),StandardCharsets.UTF_8);
        assertTrue(xml.contains("<or>"));assertTrue(xml.contains("<baseValue baseType=\"float\">2.5</baseValue>"));
        var dom=AssessmentInterchange.xml(files.get("item1.xml"));var correct=(org.w3c.dom.Element)dom.getElementsByTagNameNS("*","correctResponse").item(0);assertEquals(1,correct.getElementsByTagNameNS("*","value").getLength());
        assertTrue(new String(files.get("imsmanifest.xml"),StandardCharsets.UTF_8).contains("<dependency identifierref=\"item1\"/>"));
        var imported=AssessmentInterchange.read(files.get("item1.xml"),"item.xml");assertEquals(new java.math.BigDecimal("2.5"),DocumentIndex.of(imported.document()).items().get(0).item().points());
    }
    private AssessmentDocument sample(){return AssessmentInterchange.read(AssessmentInterchange.template("json"),"sample.json").document();}
    @ParameterizedTest @ValueSource(strings={"json","csv","xlsx","docx","qti"})
    void exportedDocumentsRoundTrip(String format){var doc=sample();var file=AssessmentInterchange.write(doc,format);var imported=AssessmentInterchange.read(file.bytes(),"test."+file.extension());assertEquals(DocumentCodec.canonicalHash(doc),DocumentCodec.canonicalHash(imported.document()));assertEquals(2,DocumentIndex.of(imported.document()).itemCount());}
    @Test void excelEditsOverrideStoredPromptAndKey(){String csv=new String(AssessmentInterchange.write(sample(),"csv").bytes(),StandardCharsets.UTF_8);csv=csv.replace("2 + 3 bằng bao nhiêu?","1 + 3 bằng bao nhiêu?");var doc=AssessmentInterchange.read(csv.getBytes(StandardCharsets.UTF_8),"test.csv").document();assertTrue(DocumentIndex.of(doc).items().get(0).item().prompt().contains("1 + 3"));}
    @Test void wordEditedBodyIsParsedRatherThanUsingStaleSnapshot(){var files=AssessmentInterchange.unzip(AssessmentInterchange.write(sample(),"docx").bytes());Map<String,String> text=new LinkedHashMap<>();files.forEach((k,v)->text.put(k,new String(v,StandardCharsets.UTF_8)));text.put("word/document.xml",text.get("word/document.xml").replace("2 + 3 bằng bao nhiêu?","1 + 3 bằng bao nhiêu?"));var imported=AssessmentInterchange.read(AssessmentInterchange.zip(text),"test.docx");assertFalse(imported.warnings().isEmpty());assertTrue(DocumentIndex.of(imported.document()).items().get(0).item().prompt().contains("1 + 3"));}
    @Test void maliciousXmlCannotLoadExternalResources(){String xml="<!DOCTYPE a [<!ENTITY file SYSTEM 'file:///etc/passwd'>]><a>&file;</a>";assertThrows(AppException.class,()->AssessmentInterchange.xml(xml.getBytes(StandardCharsets.UTF_8)));}
    @Test void zipTraversalAndDuplicateNamesAreRejected(){assertThrows(AppException.class,()->AssessmentInterchange.unzip(AssessmentInterchange.zip(Map.of("../escape","x"))));}
    @Test void oversizedArchiveEntriesAreRejected(){assertThrows(AppException.class,()->AssessmentInterchange.unzip(AssessmentInterchange.zip(Map.of("large.xml","x".repeat(5*1024*1024+1)))));}
    @Test void malformedCsvIsRejected(){assertThrows(AppException.class,()->AssessmentInterchange.csv("prompt\n\"unterminated"));}
    @Test void qtiKeysUseResponseIdentifiers(){String qti="<assessmentItem xmlns='http://www.imsglobal.org/xsd/imsqti_v2p1' title='Tổng'><responseDeclaration identifier='R'><correctResponse><value>b</value></correctResponse></responseDeclaration><itemBody><choiceInteraction responseIdentifier='R' maxChoices='1'><prompt>1+2?</prompt><simpleChoice identifier='a'>2</simpleChoice><simpleChoice identifier='b'>3</simpleChoice></choiceInteraction></itemBody></assessmentItem>";var doc=AssessmentInterchange.read(qti.getBytes(StandardCharsets.UTF_8),"test.xml").document();var item=DocumentIndex.of(doc).items().get(0).item();assertEquals("CORRECT",GradingEngine.grade(item,DocumentCodec.readTree("{\"optionId\":\"o1\"}")).correctness());}
    @Test void seededParametersSurviveReloadAndDoNotChangeTemplate(){var doc=sample();var tree=DocumentCodec.toTree(doc);var item=(com.fasterxml.jackson.databind.node.ObjectNode)tree.path("sections").get(0).path("nodes").get(0);item.put("type","Q11");item.put("prompt","{{a}} + {{b}}");item.set("interaction",DocumentCodec.readTree("{\"variables\":[{\"id\":\"a\",\"min\":1,\"max\":100,\"step\":1},{\"id\":\"b\",\"min\":1,\"max\":100,\"step\":1}]}"));item.set("answerKey",DocumentCodec.readTree("{\"expression\":\"a+b\",\"tolerance\":0}"));var template=DocumentCodec.parse(tree);var one=VariableDocument.instantiate(template,1024);var two=VariableDocument.instantiate(template,1024);assertEquals(DocumentCodec.canonicalHash(one),DocumentCodec.canonicalHash(two));assertTrue(DocumentIndex.of(template).items().get(0).item().prompt().contains("{{"));assertFalse(DocumentIndex.of(one).items().get(0).item().prompt().contains("{{"));assertTrue(DocumentIndex.of(one).items().get(0).item().answerKey().path("value").asInt()>=2);}
    @Test void codeSubmissionQueuesAutomaticWorkWithoutRunningInTransaction(){var original=DocumentIndex.of(sample()).items().get(0).item();var tree=(com.fasterxml.jackson.databind.node.ObjectNode)DocumentCodec.toTree(original);tree.put("type","Q26");var item=DocumentCodec.mapper().convertValue(tree,ItemNode.class);assertEquals("PENDING_CODE",GradingEngine.grade(item,DocumentCodec.readTree("{\"code\":\"print(1)\"}")).status());assertFalse(GradingEngine.needsTeacher(item));assertEquals("UNANSWERED",GradingEngine.grade(item,DocumentCodec.readTree("{\"code\":\"\"}")).status());}
}
